codeExamples.code:
-- Strong entity: Customer (the 'one' side)
CREATE TABLE customer (
    customer_id   INT          PRIMARY KEY,
    customer_name VARCHAR(100) NOT NULL,
    email         VARCHAR(255) UNIQUE
);

-- Strong entity: Order (the 'many' side)
-- The 1:N relationship 'places' is implemented by an FK on the child.
CREATE TABLE customer_order (
    order_id    INT  PRIMARY KEY,
    order_date  DATE NOT NULL,
    customer_id INT  NOT NULL,   -- NOT NULL = mandatory participation
    CONSTRAINT fk_order_customer
        FOREIGN KEY (customer_id) REFERENCES customer(customer_id)
);

CREATE INDEX idx_order_customer_id ON customer_order(customer_id);

CREATE TABLE student (
    student_id   INT          PRIMARY KEY,
    student_name VARCHAR(100) NOT NULL
);

CREATE TABLE course (
    course_id   INT         PRIMARY KEY,
    course_name VARCHAR(150) NOT NULL
);

-- Associative (junction) entity resolving the M:N 'enrolls in' relationship.
-- Composite PK guarantees a student enrolls in a course at most once.
CREATE TABLE enrollment (
    student_id    INT  NOT NULL,
    course_id     INT  NOT NULL,
    enrolled_on   DATE NOT NULL,        -- relationship attribute
    grade         CHAR(2),
    PRIMARY KEY (student_id, course_id),
    FOREIGN KEY (student_id) REFERENCES student(student_id),
    FOREIGN KEY (course_id)  REFERENCES course(course_id)
);
